    public static IconElement Create(string? glyph, string? path, bool symbolFont)
    {
        IconElement icon = path is string data
            ? new PathIcon { Data = ToGeometry(data) }
            : new FontIcon { Glyph = glyph ?? string.Empty };
        if (symbolFont && icon is FontIcon font && Application.Current.Resources["SymbolThemeFontFamily"] is FontFamily family)
            font.FontFamily = family;
        return icon;
    }

    // The XAML path mini-language only supports a single figure, so path data with
    // multiple 'M' subpaths (disjoint contours, e.g. icons with holes) is parsed
    // into a PathGeometry with one PathFigure per subpath instead.
    private static Geometry ToGeometry(string data)
    {
        var parts = data.Split('M');
        if (parts.Length <= 2)
            return (PathGeometry)XamlBindingHelper.ConvertValue(typeof(PathGeometry), data);

        var geometry = new PathGeometry();
        foreach (var figureData in parts.Skip(1))
        {
            var tokens = figureData.Split('L', StringSplitOptions.RemoveEmptyEntries);
            if (tokens.Length == 0) continue;
            var figure = new PathFigure { IsClosed = true, StartPoint = ParsePoint(tokens[0]) };
            foreach (var token in tokens.Skip(1))
                figure.Segments.Add(new LineSegment { Point = ParsePoint(token) });
            geometry.Figures.Add(figure);
        }
        return geometry;
    }

    private static Windows.Foundation.Point ParsePoint(string s)
    {
        var parts = s.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries);
        return new Windows.Foundation.Point(
            double.Parse(parts[0], CultureInfo.InvariantCulture),
            double.Parse(parts[1], CultureInfo.InvariantCulture));
    }
